60	        <fieldset
61	          disabled={disabled}
62	          className={cn(
63	            "border-0 p-0",
64	            containerClasses ? cn("gap-4", containerClasses) : "space-y-4",
65	          )}
66	        >
67	          {children.map((child, index) => (
68	            <QuestionField
69	              key={child.id}
70	              question={child}
71	              depth={depth + 1}
72	              number={childNumber(index)}
73	            />
74	          ))}
75	        </fieldset>
76	      </TopLevelCard>
77	    );
78	  }
