import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";

import { cn } from "@/lib/utils";

import { sanitizeStylingClasses } from "@/components/QuestionnaireV2/renderer/sanitizeStylingClasses";

import type { Question } from "@/types/questionnaire/question";

import { useFormChrome } from "./chrome";
import { QuestionBlock } from "./QuestionBlock";

/**
 * Group rendering on the one-scroll canvas. Top-level groups are the
 * reference design's "sections": soft card, accent bar, numbered title,
 * question count, children as white question cards. Nested groups keep the
 * old renderer's two-tone treatment. Both preserve the deployed contracts:
 * `<fieldset disabled>` threads disabled state to native children,
 * `styling_metadata.classes` decorates the wrapper, `containerClasses` lays
 * out the sub-question container — all through `sanitizeStylingClasses`.
 */
export function SectionCard({
  question,
  depth,
  disabled,
  number,
}: {
  question: Question;
  depth: number;
  disabled: boolean;
  /** Dotted ordinal matching the tree nav (e.g. "7."); children derive
   *  "7.1.", "7.2.", … from it. */
  number?: string;
}) {
  const { t } = useTranslation();
  const { AppendZone } = useFormChrome();
  const children = question.questions ?? [];
  const leafChildCount = children.filter(
    (child) => child.type !== "group",
  ).length;

  const decorationClasses = sanitizeStylingClasses(
    question.styling_metadata?.classes,
  );
  const containerClasses = sanitizeStylingClasses(
    question.styling_metadata?.containerClasses,
  );

  const childNumber = (index: number) =>
    number ? `${number}${index + 1}.` : undefined;

  const renderChildren = () =>
    children.map((child, index) => (
      <QuestionBlock
        key={child.id}
        question={child}
        parentId={question.id}
        index={index}
        siblingCount={children.length}
        depth={depth + 1}
        number={childNumber(index)}
      />
    ));

  if (depth === 0) {
    return (
      <section
        className={cn(
          "rounded-xl border border-gray-200 bg-gray-50 p-3.5",
          decorationClasses,
        )}
      >
        <div className="mb-3 flex items-center gap-2">
          <span
            aria-hidden
            className="h-4 w-1 shrink-0 rounded-full bg-primary-600"
          />
          <h3 className="text-sm font-semibold text-gray-900">
            {number && <span className="mr-1 tabular-nums">{number}</span>}
            {question.text}
          </h3>
          <Badge variant="outline">{t("group")}</Badge>
          <span className="ml-auto text-xs text-gray-400">
            {t("questions_count", { count: leafChildCount })}
          </span>
        </div>
        {question.description && (
          <p className="-mt-1 mb-3 text-xs text-gray-500">
            {question.description}
          </p>
        )}
        <fieldset
          disabled={disabled}
          className={cn(
            "border-0 p-0",
            containerClasses ? cn("gap-3", containerClasses) : "space-y-3",
          )}
        >
          {renderChildren()}
        </fieldset>
        {AppendZone && <AppendZone parentId={question.id} />}
      </section>
    );
  }

  // Nested group: two-tone box — the title sits in its own darker header
  // strip with a lighter inset body panel beneath it.
  return (
    <div
      className={cn(
        "overflow-hidden rounded-md border border-gray-200 bg-gray-200/60",
        decorationClasses,
      )}
    >
      <h4 className="px-3 py-1.5 text-sm font-semibold text-gray-900">
        {number && <span className="mr-1 tabular-nums">{number}</span>}
        {question.text}
      </h4>
      <fieldset
        disabled={disabled}
        className={cn(
          "m-1 gap-4 rounded border-0 bg-gray-50 p-2",
          containerClasses ??
            cn("grid sm:grid-cols-2", leafChildCount >= 3 && "sm:grid-cols-3"),
        )}
      >
        {renderChildren()}
      </fieldset>
      {AppendZone && <AppendZone parentId={question.id} />}
    </div>
  );
}

import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { useVisibleTopLevelIndices } from "@/components/QuestionnaireV2/renderer/store";

import type { Question } from "@/types/questionnaire/question";
import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";

import { FormChrome, FormChromeProvider, useFormChrome } from "./chrome";
import { QuestionnaireFormProvider, useFormRenderer } from "./FormContext";
import { QuestionBlock } from "./QuestionBlock";
import type { FormMode, RendererSubject } from "./types";

export interface QuestionnaireFormRendererProps {
  questionnaire: QuestionnaireRead;
  mode: FormMode;
  subject?: RendererSubject;
  /** Builder edit canvas: render enable_when-hidden questions too. */
  revealHidden?: boolean;
  /** Builder edit canvas: inputs visible but non-interactive. */
  inert?: boolean;
  /** Decoration seam — see chrome.tsx. */
  chrome?: FormChrome;
  /** Replaces the default "no questions" text (the studio passes its
   *  add-first/import affordances). */
  emptyState?: React.ReactNode;
  /** Hide the questionnaire title/description header (hosts that already
   *  show them elsewhere). */
  hideHeader?: boolean;
  className?: string;
}

function countLeafQuestions(questions: Question[]): number {
  let count = 0;
  const walk = (list: Question[]) => {
    for (const question of list) {
      if (question.type === "group") walk(question.questions ?? []);
      else count += 1;
    }
  };
  walk(questions);
  return count;
}

/**
 * The full renderer: the whole questionnaire on one scroll — top-level
 * groups as section cards, everything live against the per-instance store.
 * This is the module the builder canvas, preview and (next phase) the fill
 * flow all mount; the old paginated renderer stays untouched until removal.
 */
export function QuestionnaireFormRenderer({
  questionnaire,
  mode,
  subject,
  revealHidden,
  inert,
  chrome = {},
  emptyState,
  hideHeader,
  className,
}: QuestionnaireFormRendererProps) {
  return (
    <QuestionnaireFormProvider
      questionnaire={questionnaire}
      mode={mode}
      subject={subject}
      revealHidden={revealHidden}
      inert={inert}
    >
      <FormChromeProvider chrome={chrome}>
        <CanvasBody
          emptyState={emptyState}
          hideHeader={hideHeader}
          className={className}
        />
      </FormChromeProvider>
    </QuestionnaireFormProvider>
  );
}

/**
 * The canvas body for hosts that mount `QuestionnaireFormProvider`
 * themselves — the studio does, so its outline and canvas share one store
 * (the outline's preview mode reads live enable_when hidden ids).
 */
export function QuestionnaireFormCanvas({
  chrome = {},
  emptyState,
  hideHeader,
  className,
}: {
  chrome?: FormChrome;
  emptyState?: React.ReactNode;
  hideHeader?: boolean;
  className?: string;
}) {
  return (
    <FormChromeProvider chrome={chrome}>
      <CanvasBody
        emptyState={emptyState}
        hideHeader={hideHeader}
        className={className}
      />
    </FormChromeProvider>
  );
}

function CanvasBody({
  emptyState,
  hideHeader,
  className,
}: {
  emptyState?: React.ReactNode;
  hideHeader?: boolean;
  className?: string;
}) {
  const { t } = useTranslation();
  const { questionnaire, revealHidden } = useFormRenderer();
  const { AppendZone } = useFormChrome();
  const visibleIndices = useVisibleTopLevelIndices();
  const questions = questionnaire.questions;

  const header = !hideHeader && (
    <div className="space-y-1 pb-4">
      <h2 className="text-lg font-semibold tracking-tight text-gray-900">
        {questionnaire.title}
      </h2>
      {questionnaire.description && (
        <p className="text-sm text-gray-500">{questionnaire.description}</p>
      )}
      {questions.length > 0 && (
        <p className="text-xs text-gray-400">
          {t("questions_count", { count: countLeafQuestions(questions) })}
        </p>
      )}
    </div>
  );

  if (questions.length === 0) {
    return (
      <div className={cn("mx-auto w-full max-w-3xl", className)}>
        {header}
        {emptyState ?? (
          <div className="rounded-lg bg-white p-8 text-center text-sm text-gray-500">
            {t("no_questions_added_yet")}
          </div>
        )}
      </div>
    );
  }

  // Every top-level question hidden by enable_when: explain the empty form
  // instead of a blank canvas. The edit canvas (`revealHidden`) never hits
  // this — hidden questions render there with a logic badge.
  if (!revealHidden && visibleIndices.length === 0) {
    return (
      <div className={cn("mx-auto w-full max-w-3xl", className)}>
        {header}
        <div className="p-8 text-center text-sm text-gray-500">
          {t("no_visible_questions")}
        </div>
      </div>
    );
  }

  return (
    <div className={cn("mx-auto w-full max-w-3xl", className)}>
      {header}
      <div className="space-y-4 pb-4">
        {questions.map((question, index) => (
          <QuestionBlock
            key={question.id}
            question={question}
            parentId={null}
            index={index}
            siblingCount={questions.length}
            depth={0}
            number={`${index + 1}.`}
          />
        ))}
        {AppendZone && <AppendZone parentId={null} />}
      </div>
    </div>
  );
}

